(()=>{'use strict';
const API='https://woongbi-quote-api.woongbts.workers.dev/quote/studyphone';
let loading=null,snapshot=null,lastError=null;
async function request(body={}){const response=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw Error('studyphone-api-'+response.status);const data=await response.json();if(!data||data.ok!==true)throw Error('studyphone-api-invalid');return data}
function publishReady(data){snapshot=data;lastError=null;document.documentElement.dataset.studyphoneApi='ready';try{window.dispatchEvent(new CustomEvent('woongbi:studyphone-ready',{detail:{updatedAt:data?.meta?.updated_at||'',items:Array.isArray(data?.items)?data.items.length:0}}))}catch{}return data}
function publishError(error){lastError=error;document.documentElement.dataset.studyphoneApi='unavailable';try{window.dispatchEvent(new CustomEvent('woongbi:studyphone-unavailable'))}catch{}throw error}
async function load(force=false){if(snapshot&&!force)return snapshot;if(loading&&!force)return loading;document.documentElement.dataset.studyphoneApi='loading';loading=request({}).then(publishReady).catch(publishError).finally(()=>{loading=null});return loading}
function item(planId){if(!snapshot||!Array.isArray(snapshot.items))return null;return snapshot.items.find(entry=>entry?.plan?.id===planId)||null}
async function quote(planId){const id=String(planId||'').trim();if(!id)return null;const cached=item(id);if(cached)return cached;const data=await request({plan_id:id});return data?.item||null}
window.WoongbiStudyphoneApi={load,item,quote,snapshot:()=>snapshot,error:()=>lastError,ready:()=>document.documentElement.dataset.studyphoneApi==='ready'};
})();
